import React, { useState, useEffect, useCallback } from 'react';
import AnalysisModal from './components/AnalysisModal';
import { StandingsModal } from './StandingsModal';
import PlayoffBracket from './components/PlayoffBracket';
import { UserPrediction, Game } from './types';
import { espnApi } from './services/espnAdapter';
import { userService } from './services/userService';
import { AuthProvider, useAuth } from './context/AuthContext';
import { AuthStatus } from './components/AuthStatus';
import { downloadPredictionsAsCSV } from './utils/csvExporter';
import { CURRENT_SEASON, SEASON_STAGES, SeasonStage } from './data/nfl_data';
import { DATA_ATTRIBUTION } from './data/teamStats';
import { Calendar, MapPin, ChevronRight, RefreshCw, Server, Loader2, Download, Trophy, GitBranch, AlertCircle } from 'lucide-react';

export async function backfillUnresolvedResults(
  predictions: Record<string, UserPrediction>,
  currentResults: Record<string, any>,
  fetchSchedule: (week?: number, seasonType?: number) => Promise<{ data: Game[] }> = espnApi.getSchedule
): Promise<Record<string, any>> {
  const unresolvedPreds = Object.values(predictions).filter(p => !currentResults[p.gameId]);
  if (unresolvedPreds.length === 0) return currentResults;

  const weeksToFetch = new Set<number>();
  let hasUnspecifiedWeeks = false;

  for (const p of unresolvedPreds) {
    if (p.week) {
      weeksToFetch.add(p.week);
    } else {
      hasUnspecifiedWeeks = true;
    }
  }

  if (hasUnspecifiedWeeks) {
    SEASON_STAGES.forEach(s => weeksToFetch.add(s.week));
  }

  let nextResults = { ...currentResults };
  let changed = false;

  for (const week of Array.from(weeksToFetch)) {
    const stage = SEASON_STAGES.find(s => s.week === week) || { week, seasonType: 2 };
    try {
      const resp = await fetchSchedule(stage.week, stage.seasonType);
      for (const g of resp.data || []) {
        if (g.status === 'post' && g.homeTeam.score !== undefined && g.awayTeam.score !== undefined) {
          if (!nextResults[g.id]) {
            nextResults[g.id] = {
              homeScore: g.homeTeam.score,
              awayScore: g.awayTeam.score,
              spread: g.bettingData?.spread || "",
              homeAbbr: g.homeTeam.abbreviation,
              awayAbbr: g.awayTeam.abbreviation,
              homeName: g.homeTeam.name,
              awayName: g.awayTeam.name,
              week: g.week
            };
            changed = true;
          }
        }
      }
    } catch (err) {
      console.warn(`Failed to backfill results for week ${week}:`, err);
    }
  }

  return changed ? nextResults : currentResults;
}

const MediPicksApp: React.FC = () => {
  const { user, loading: authLoading } = useAuth();
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [showStandings, setShowStandings] = useState(false);
  const [view, setView] = useState<'games' | 'bracket'>('games');
  
  // Data State
  const [userPredictions, setUserPredictions] = useState<Record<string, UserPrediction>>({});
  const [gameResults, setGameResults] = useState<Record<string, any>>(() => {
    const saved = localStorage.getItem('mediPicks_results');
    return saved ? JSON.parse(saved) : {};
  });

  const [games, setGames] = useState<Game[]>([]);
  const [dataLoading, setDataLoading] = useState(true);
  const [meta, setMeta] = useState<any>(null);
  const [currentStage, setCurrentStage] = useState<SeasonStage>(SEASON_STAGES[0]); // Default to Week 1

  // Load User Data on Auth Change
  useEffect(() => {
    const loadData = async () => {
      if (authLoading) return;
      const preds = await userService.loadPredictions(user?.uid);
      setUserPredictions(preds);

      // Backfill results for unresolved picks across all weeks using current saved results
      const saved = localStorage.getItem('mediPicks_results');
      const current = saved ? JSON.parse(saved) : {};
      const updatedResults = await backfillUnresolvedResults(preds, current);
      if (updatedResults !== current) {
        setGameResults(updatedResults);
      }
    };
    loadData();
  }, [user, authLoading]);

  const fetchData = useCallback(async (stage: SeasonStage) => {
    setDataLoading(true);
    try {
      const response = await espnApi.getSchedule(stage.week, stage.seasonType);
      setGames(response.data);
      setMeta(response.meta);
    } catch (error) {
      console.error("Failed to fetch ESPN data", error);
      setMeta({ status: "ERROR", season: CURRENT_SEASON, week: stage.week });
    } finally {
      setDataLoading(false);
    }
  }, []);

  // Initial Fetch & Auto-Refresh (Realtime)
  useEffect(() => {
    if (view === 'games') {
      fetchData(currentStage);
      const interval = setInterval(() => fetchData(currentStage), 60000); // 60s Refresh
      return () => clearInterval(interval);
    }
  }, [currentStage, view, fetchData]);

  // Save & Update Results (Local Only for completed games)
  useEffect(() => {
    localStorage.setItem('mediPicks_results', JSON.stringify(gameResults));
  }, [gameResults]);

  // Check for Completed Games to Update Results Cache
  useEffect(() => {
    if (games.length === 0) return;
    
    setGameResults(prev => {
      const next = { ...prev };
      let changed = false;
      
      games.forEach(g => {
        if (g.status === 'post' && g.homeTeam.score !== undefined && g.awayTeam.score !== undefined) {
          if (!next[g.id]) {
            next[g.id] = {
              homeScore: g.homeTeam.score,
              awayScore: g.awayTeam.score,
              spread: g.bettingData?.spread || "",
              homeAbbr: g.homeTeam.abbreviation,
              awayAbbr: g.awayTeam.abbreviation,
              homeName: g.homeTeam.name,
              awayName: g.awayTeam.name,
              week: g.week
            };
            changed = true;
          }
        }
      });
      return changed ? next : prev;
    });
  }, [games]);

  const handleSavePrediction = async (prediction: UserPrediction) => {
    const newPredictions = {
      ...userPredictions,
      [prediction.gameId]: prediction
    };
    setUserPredictions(newPredictions);
    await userService.savePredictions(user?.uid, newPredictions);
    setSelectedGame(null);
  };

  const handleDownload = () => {
    if (games.length > 0) {
      downloadPredictionsAsCSV(games, userPredictions, gameResults);
    }
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><Loader2 className="animate-spin text-blue-500 w-8 h-8"/></div>;

  const regStages = SEASON_STAGES.filter(s => s.seasonType === 2);
  const playoffStages = SEASON_STAGES.filter(s => s.seasonType === 3);

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans selection:bg-blue-500/30">
      
      {/* App Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-10 shadow-xl">
        <div className="max-w-7xl mx-auto px-4 py-4 flex flex-col items-center gap-4">
          <div className="w-full flex flex-col md:flex-row items-center justify-between gap-4 md:gap-0">
            <div>
              <h1 className="text-2xl font-black tracking-tighter text-white flex items-center gap-2">
                MEDI PICKS <span className="text-blue-500">{CURRENT_SEASON}</span>
              </h1>
              <p className="text-xs text-slate-400 font-medium tracking-wide uppercase flex items-center gap-2 mt-1">
                {currentStage.label} • Season {meta?.season || CURRENT_SEASON}
                <span className="text-slate-600">|</span>
                <Server className="w-3 h-3 text-slate-500" />
                <span className="text-slate-500">ESPN Realtime</span>
              </p>
            </div>
            
            <div className="flex items-center gap-3">
              <div className="bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-700 text-xs font-bold text-slate-300 hidden md:block">
                {Object.keys(userPredictions).length} Predictions Saved
              </div>

              <AuthStatus />

              <div className="w-px h-6 bg-slate-700 mx-1"></div>

              <button 
                onClick={() => setShowStandings(true)}
                className="flex items-center gap-2 px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-yellow-400 rounded-lg transition-colors text-xs font-bold border border-slate-700"
                title="View Standings"
              >
                <Trophy className="w-4 h-4" />
                <span className="hidden sm:inline">Standings</span>
              </button>

              <button 
                onClick={() => setView(view === 'games' ? 'bracket' : 'games')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg transition-colors text-xs font-bold border border-slate-700 ${view === 'bracket' ? 'bg-blue-600 text-white' : 'bg-slate-800 hover:bg-slate-700 text-slate-300'}`}
                title="View Bracket"
              >
                <GitBranch className="w-4 h-4" />
                <span className="hidden sm:inline">Bracket</span>
              </button>
              
              <button 
                onClick={handleDownload}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg transition-colors text-xs font-bold shadow-lg shadow-blue-900/20 active:scale-95"
                title="Download Predictions CSV"
              >
                <Download className="w-4 h-4" />
                <span className="hidden sm:inline">Export</span>
              </button>

              <div className="w-px h-6 bg-slate-700 mx-1"></div>

              <button 
                onClick={() => fetchData(currentStage)}
                className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors border border-slate-700 text-slate-400 hover:text-white"
                title="Refresh Live Data"
              >
                <RefreshCw className={`w-4 h-4 ${dataLoading && games.length === 0 ? 'animate-spin' : ''}`} />
              </button>
            </div>
          </div>

          {/* Week Selector Tabs (22 Stages) */}
          {view === 'games' && (
            <div className="w-full flex items-center gap-1.5 overflow-x-auto pb-2 md:pb-0 scrollbar-hide">
              {/* Regular Season Group */}
              <div className="flex items-center gap-1">
                {regStages.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => setCurrentStage(s)}
                    className={`px-3 py-1 rounded-full text-xs font-bold transition-all whitespace-nowrap ${
                      currentStage.id === s.id 
                        ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' 
                        : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'
                    }`}
                  >
                    {s.label}
                  </button>
                ))}
              </div>

              {/* Visual Separator */}
              <div className="h-6 w-px bg-slate-700 mx-2 flex-shrink-0"></div>

              {/* Playoff Group */}
              <div className="flex items-center gap-1">
                {playoffStages.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => setCurrentStage(s)}
                    className={`px-3 py-1 rounded-full text-xs font-bold transition-all whitespace-nowrap ${
                      currentStage.id === s.id 
                        ? 'bg-yellow-500 text-slate-950 font-black shadow-lg shadow-yellow-900/50' 
                        : 'bg-slate-800/80 text-yellow-400/80 hover:bg-slate-700 hover:text-yellow-300 border border-yellow-500/20'
                    }`}
                  >
                    {s.label}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 py-8">
        {view === 'bracket' ? (
          <PlayoffBracket />
        ) : meta?.status === "ERROR" ? (
          <div className="flex flex-col items-center justify-center py-16 bg-red-950/20 border border-red-800/50 rounded-2xl p-8 text-center max-w-lg mx-auto">
            <AlertCircle className="w-12 h-12 text-red-400 mb-4" />
            <h3 className="text-lg font-bold text-white mb-2">Unable to Load Schedule</h3>
            <p className="text-sm text-slate-400 mb-6">Failed to retrieve data for {currentStage.label}. Please try refreshing.</p>
            <button
              onClick={() => fetchData(currentStage)}
              className="px-6 py-2.5 bg-red-600 hover:bg-red-500 text-white rounded-lg text-xs font-bold transition-all shadow-lg"
            >
              Retry Schedule Fetch
            </button>
          </div>
        ) : dataLoading && games.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64">
            <Loader2 className="w-12 h-12 text-blue-500 animate-spin mb-4" />
            <p className="text-slate-400 animate-pulse text-sm uppercase tracking-widest">Loading {CURRENT_SEASON} Schedule...</p>
          </div>
        ) : games.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 bg-slate-900/50 border border-slate-800 rounded-2xl p-8 text-center max-w-lg mx-auto">
            <Calendar className="w-12 h-12 text-slate-600 mb-4" />
            <h3 className="text-lg font-bold text-white mb-2">No Games Scheduled</h3>
            <p className="text-sm text-slate-400">No games are scheduled for {currentStage.label} of season {CURRENT_SEASON}.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {games.map((game) => {
              const prediction = userPredictions[game.id];
              const isPreGame = game.status === 'pre' || !game.status;
              
              return (
                <div 
                  key={game.id}
                  onClick={() => setSelectedGame(game)}
                  className="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden hover:border-blue-500/50 hover:shadow-2xl hover:shadow-blue-900/20 transition-all duration-300 cursor-pointer group relative"
                >
                  {/* Prediction Overlay Badge (Requirement 4) */}
                  {prediction && (
                    <div className="absolute top-[44px] right-2 flex flex-col items-end gap-1 z-10">
                      {prediction.agreementState === 'agreed' ? (
                        <div className="bg-emerald-950/80 border border-emerald-600 text-emerald-300 text-[10px] font-bold px-2 py-0.5 rounded shadow-sm">
                          AGREED
                        </div>
                      ) : prediction.agreementState === 'deviated' ? (
                        <div className="bg-amber-950/80 border border-amber-600 text-amber-300 text-[10px] font-bold px-2 py-0.5 rounded shadow-sm">
                          DEVIATED
                        </div>
                      ) : (
                        <div className="bg-blue-500/20 border border-blue-500/50 text-blue-400 text-[10px] font-bold px-2 py-0.5 rounded shadow-sm">
                          PICK LOCKED
                        </div>
                      )}

                      {game.status === 'post' && (
                        <>
                          {(() => {
                            const actualWinner = (game.homeTeam.score || 0) > (game.awayTeam.score || 0) 
                              ? game.homeTeam.name 
                              : ((game.awayTeam.score || 0) > (game.homeTeam.score || 0) ? game.awayTeam.name : 'Tie');

                            const userHit = prediction.userPredictedWinner === actualWinner;
                            const engineHit = prediction.predictedWinner === actualWinner;

                            if (prediction.agreementState === 'deviated') {
                              if (userHit && !engineHit) {
                                return (
                                  <div className="px-2 py-0.5 rounded border text-[10px] font-bold bg-emerald-900/80 border-emerald-500 text-emerald-300 shadow-sm">
                                    YOU BEAT AI 🏆
                                  </div>
                                );
                              } else if (engineHit && !userHit) {
                                return (
                                  <div className="px-2 py-0.5 rounded border text-[10px] font-bold bg-rose-900/80 border-rose-500 text-rose-300 shadow-sm">
                                    AI BEAT YOU 🤖
                                  </div>
                                );
                              } else if (userHit && engineHit) {
                                return (
                                  <div className="px-2 py-0.5 rounded border text-[10px] font-bold bg-blue-900/80 border-blue-500 text-blue-300 shadow-sm">
                                    BOTH WON 🤝
                                  </div>
                                );
                              } else {
                                return (
                                  <div className="px-2 py-0.5 rounded border text-[10px] font-bold bg-slate-800 border-slate-700 text-slate-400 shadow-sm">
                                    BOTH MISSED ❌
                                  </div>
                                );
                              }
                            } else {
                              return (
                                <div className={`px-2 py-0.5 rounded border text-[10px] font-bold ${engineHit ? 'bg-green-900/50 border-green-500 text-green-400' : 'bg-red-900/50 border-red-500 text-red-400'}`}>
                                  {engineHit ? 'WINNER ✅' : 'WINNER ❌'}
                                </div>
                              );
                            }
                          })()}
                        </>
                      )}
                    </div>
                  )}

                  {/* Date & Venue / Live Status */}
                  <div className="px-4 py-3 bg-slate-950/50 border-b border-slate-800 flex justify-between items-center text-[10px] text-slate-400 font-medium uppercase tracking-wider">
                    <div className="flex items-center gap-1">
                      <Calendar className="w-3 h-3" />
                      {new Date(game.date).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}
                    </div>
                    {game.status === 'in' ? (
                      <div className="flex items-center gap-1 text-red-500 font-bold animate-pulse">
                        <span className="w-2 h-2 rounded-full bg-red-500"></span>
                        LIVE • {game.clock}
                      </div>
                    ) : game.status === 'post' ? (
                      <div className="font-bold text-slate-300">FINAL</div>
                    ) : (
                      <div className="flex items-center gap-1">
                        <MapPin className="w-3 h-3" />
                        {game.venue ? game.venue.split(' ')[0] : 'TBD'}
                      </div>
                    )}
                  </div>

                  {/* Matchup Content */}
                  <div className="p-5 flex flex-col justify-center gap-4">
                    
                    {/* Away Team */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <img src={game.awayTeam.logoUrl} alt={game.awayTeam.abbreviation} className="w-10 h-10 object-contain drop-shadow-lg" />
                        <div>
                          <div className="text-xl font-bold text-white leading-none">{game.awayTeam.abbreviation}</div>
                          <div className="text-[10px] text-slate-500 font-bold">
                            {game.awayTeam.name.split(' ').pop()} <span className="text-slate-600 font-normal">({game.awayTeam.record || "0-0"})</span>
                          </div>
                        </div>
                      </div>
                      {!isPreGame && game.awayTeam.score !== undefined ? (
                        <span className="text-2xl font-mono font-black text-white">{game.awayTeam.score}</span>
                      ) : (
                        <span className="text-xs font-mono text-slate-600">--</span>
                      )}
                    </div>

                    {/* VS Divider */}
                    <div className="w-full h-px bg-slate-800 relative">
                      <span className="absolute left-1/2 -translate-x-1/2 -translate-y-1/2 bg-slate-900 px-2 text-[10px] text-slate-600 font-bold">@</span>
                    </div>

                    {/* Home Team */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <img src={game.homeTeam.logoUrl} alt={game.homeTeam.abbreviation} className="w-10 h-10 object-contain drop-shadow-lg" />
                        <div>
                          <div className="text-xl font-bold text-white leading-none">{game.homeTeam.abbreviation}</div>
                          <div className="text-[10px] text-slate-500 font-bold">
                            {game.homeTeam.name.split(' ').pop()} <span className="text-slate-600 font-normal">({game.homeTeam.record || "0-0"})</span>
                          </div>
                        </div>
                      </div>
                      {!isPreGame && game.homeTeam.score !== undefined ? (
                        <span className="text-2xl font-mono font-black text-white">{game.homeTeam.score}</span>
                      ) : (
                        <span className="text-xs font-mono text-slate-600">--</span>
                      )}
                    </div>

                  </div>

                  {/* Call to Action Footer */}
                  <div className="px-4 py-3 bg-slate-800/30 border-t border-slate-800 flex items-center justify-between group-hover:bg-blue-600/10 transition-colors">
                    <span className="text-xs font-bold text-blue-400 group-hover:text-blue-300">
                      {prediction ? 'View Analysis' : 'Analyze Matchup'}
                    </span>
                    <ChevronRight className="w-4 h-4 text-slate-500 group-hover:text-blue-400 transform group-hover:translate-x-1 transition-transform" />
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </main>

      {/* Modal Layers */}
      {selectedGame && (
        <AnalysisModal 
          game={selectedGame} 
          onClose={() => setSelectedGame(null)} 
          userPrediction={userPredictions[selectedGame.id]}
          onSavePrediction={handleSavePrediction}
        />
      )}
      
      {showStandings && (
        <StandingsModal 
          onClose={() => setShowStandings(false)} 
          predictions={userPredictions}
          results={gameResults}
        />
      )}

      {/* Footer Disclaimer & Data Attribution */}
      <footer className="max-w-7xl mx-auto px-4 py-8 border-t border-slate-900 mt-8 space-y-3">
        <p className="text-[12px] leading-relaxed text-slate-500 text-center max-w-3xl mx-auto">
          {DATA_ATTRIBUTION}
        </p>
        <p className="text-[12px] leading-relaxed text-slate-600 text-center max-w-3xl mx-auto">
          Disclaimer: This application and the NFL picks provided herein are for educational and entertainment purposes only. 
          All information is intended to enhance the fan experience and should not be construed as professional financial or legal advice. 
          We do not offer real-money gambling or sports betting services. Betting involves significant risk, and we are not responsible 
          for any financial losses or damages resulting from the use of the information on this site. If you or someone you know 
          has a gambling problem, please call 1-800-GAMBLER. Must be 21+ to participate in sports wagering.
        </p>
      </footer>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <MediPicksApp />
    </AuthProvider>
  );
};

export default App;